// Node's own resolution rule sends this require to vt2-runner-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// The only call to the vulnerable export anywhere in this project. It is
// reached ONLY through the application's own exported `main`, which is
// reached ONLY if the entrypoint's callable surface is rooted at all.
function run(input) {
  return dep.dangerousOp(input);
}

exports.run = run;
